// The committed API report of one core package (PRODUCT spec §2 F6): a heading per entry point, a heading and
// a `ts` block per export. It carries no version, so a release alone never makes it stale. `parseReport` reads
// it back, so the break check can compare the report on `origin/main` with the current API.
import type { ApiEntry, ApiExport, ApiKind, PackageApi } from './extract.ts'

export interface ParsedReport {
  readonly package: string
  readonly entries: readonly ApiEntry[]
}

const NOTE =
  '<!-- Generated by `pnpm api-report --update` from source. Do not edit. A change here is a change to the public API (PRODUCT spec §2 F6). -->'

export function renderReport(api: PackageApi): string {
  const lines = [`# ${api.package} API report`, '', NOTE]
  for (const entry of api.entries) {
    lines.push('', `## \`${entry.entryPoint}\``)
    for (const exported of entry.exports) {
      lines.push('', `### \`${exported.name}\` (${exported.kind})`, '', '```ts', exported.declaration, '```')
    }
  }
  return `${lines.join('\n')}\n`
}

const PACKAGE = /^# (\S+) API report$/
const ENTRY = /^## `([^`]+)`$/
const EXPORT = /^### `([^`]+)` \((\w+)\)$/

export function parseReport(text: string): ParsedReport {
  const lines = text.split('\n')
  let name = ''
  const entries: Array<{ entryPoint: string; exports: ApiExport[] }> = []
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index] ?? ''
    const packageMatch = PACKAGE.exec(line)
    if (packageMatch !== null) name = packageMatch[1] ?? ''
    const entryMatch = ENTRY.exec(line)
    if (entryMatch !== null) entries.push({ entryPoint: entryMatch[1] ?? '', exports: [] })
    const exportMatch = EXPORT.exec(line)
    if (exportMatch !== null) {
      // The ts block starts two lines down and runs to the closing fence.
      const body: string[] = []
      index += 3
      while (index < lines.length && lines[index] !== '```') body.push(lines[index++] ?? '')
      entries.at(-1)?.exports.push({
        name: exportMatch[1] ?? '',
        kind: (exportMatch[2] ?? 'other') as ApiKind,
        declaration: body.join('\n'),
      })
    }
  }
  return { package: name, entries }
}
